const input = $json;
const payload = input.calendarPayload || {};

function toGoogleLocalDateTime(value) {
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) {
    throw new Error(`Invalid Calendar date: ${value}`);
  }

  const parts = new Intl.DateTimeFormat('sv-SE', {
    timeZone: payload.timezone || 'Europe/Paris',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hour12: false
  }).formatToParts(date);

  const values = Object.fromEntries(parts.map((part) => [part.type, part.value]));
  return `${values.year}-${values.month}-${values.day}T${values.hour}:${values.minute}:${values.second}`;
}

const event = {
  summary: payload.summary || input.meeting?.title || 'FamilyHubOS meeting',
  description: payload.description || '',
  start: {
    dateTime: toGoogleLocalDateTime(payload.start || input.meeting?.date || new Date().toISOString()),
    timeZone: payload.timezone || 'Europe/Paris'
  },
  end: {
    dateTime: toGoogleLocalDateTime(payload.end || new Date(Date.now() + 60 * 60 * 1000).toISOString()),
    timeZone: payload.timezone || 'Europe/Paris'
  }
};

return [{
  json: {
    ...input,
    googleCalendarEventPayload: event
  }
}];

