const failed = Boolean(calendarResponse.error || calendarResponse.message?.includes?.('error'));

const lines = [
  'Page Notion créée.',
  '',
  `Sujet: ${topic}`,
  notionUrl ? `Notion: ${notionUrl}` : null,
  failed ? 'Calendrier: création à vérifier dans n8n.' : (calendarUrl ? `Calendrier: ${calendarUrl}` : 'Calendrier: événement créé.')
].filter(Boolean);

return [{
  json: {
    ...previous,
    calendarEvent: failed ? null : calendarResponse,
    calendarEventUrl: failed ? null : calendarUrl,
    calendarCreateStatus: failed ? 'FAILED_OR_UNKNOWN' : 'CREATED',
    telegramReplyMarkup: null,
    responseText: lines.join('\n')
  }
}];
